def intersection(interval1, interval2):
    """Determine if the length of intersection of two intervals is a prime number."""
    def is_prime(n):
        """Helper function to check if a number is prime."""
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Calculate the intersection of intervals
    start_intersection = max(interval1[0], interval2[0])
    end_intersection = min(interval1[1], interval2[1])

    # Check if the intervals overlap
    if start_intersection <= end_intersection:
        length = end_intersection - start_intersection + 1  # Length of intersection
        return "YES" if is_prime(length) else "NO"
    return "NO"
