from itertools import combinations

def is_multiply_prime(a):
    """Returns True if the given number is the product of exactly three prime numbers and False otherwise."""
    def is_prime(n):
        """Helper function to check if a number is prime."""
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Generate all primes less than 100
    primes = [n for n in range(2, 100) if is_prime(n)]

    # Check all combinations of three distinct primes
    for combo in combinations(primes, 3):
        if combo[0] * combo[1] * combo[2] == a:
            return True

    return False
